  ('74690ba3-e4a3-5193-a4fd-bed2eb15e365', 'f16a84c7-3394-5faf-ae45-933191ffcd71', 'c4e08204-ad04-5e49-aca9-12e5cde0c7b5', 'memo', '26af4625-d600-595e-a607-2d03feb48d68', null, 'Vult', 'Co-pilot', 'Each 100bp cut is about $21m of revenue. I suggested a sentence: the downside case gives $24.47.', now() - interval '9 minutes' + interval '1 minute'),
  ('9d6cabde-5157-5917-af35-d37205906dbb', 'f16a84c7-3394-5faf-ae45-933191ffcd71', 'c4e08204-ad04-5e49-aca9-12e5cde0c7b5', 'memo', null, null, 'Marcus Bell', 'Associate', 'Do we have pricing for Gridline’s bundle?', now() - interval '27 minutes'),
  ('ddbeb753-53d0-5291-ad88-bc4d4bd5d030', 'f16a84c7-3394-5faf-ae45-933191ffcd71', 'c4e08204-ad04-5e49-aca9-12e5cde0c7b5', 'memo', '9d6cabde-5157-5917-af35-d37205906dbb', null, 'Vult', 'Co-pilot', 'Yes, from their 10-K and the pricing page captured on 8 Oct 2026. Linked as source 5.', now() - interval '27 minutes' + interval '1 minute');
