  ('c1fac595-8f38-5ea1-abe6-c475db415d0e', 'f16a84c7-3394-5faf-ae45-933191ffcd71', 'earnings', 'gold', 'Earnings flash', 'Orion Field Services Q3 results land on Thursday after the close', 'The flash is armed: a two-page note against your model, ready about 30 minutes after the release, then sent to the Mesa deal team.', 'Scheduled', '{"label":"See Autopilot","view":"autopilot","tab":null}'::jsonb, ((date_trunc('day', (now() at time zone 'America/New_York')) + (((4 - extract(isodow from (now() at time zone 'America/New_York'))::int + 6) % 7) + 1) * interval '1 day' + time '16:05') at time zone 'America/New_York'), 2);
